import '../config.dart';
import '../ir.dart';
import 'strings.dart';
import 'uris.dart';

/// Name of the widget extension target, folder and product.
const iosExtensionName = 'FNWWidgets';

/// Native output for iOS: path relative to `ios/` → content.
Map<String, String> emitIos(List<WidgetIR> widgets, ProjectConfig config) => {
  '$iosExtensionName/$iosExtensionName.swift': _IosEmitter(
    widgets,
    config,
  ).emit(),
  'Runner/FNWCallbackIntent.swift': callbackIntentSwift,
};

const _swiftHeader =
    '// GENERATED CODE - DO NOT MODIFY BY HAND\n'
    '// Generated by flutter_native_widget_gen from your @HomeScreenWidget classes.\n';

/// App-target half of the callback intent: runs your `@WidgetCallback` Dart
/// functions through home_widget. The extension has a stand-in with the same
/// name and parameters (see `_callbackIntentStub`) so buttons can refer to
/// it; the system then performs this one, in the app.
///
/// Two files instead of one shared file with `#if canImport(home_widget)`:
/// the extension can see the home_widget module in the build folder without
/// linking it, which fails at link time.
const callbackIntentSwift =
    '''
$_swiftHeader
import AppIntents
import Foundation
import WidgetKit
import home_widget

@available(iOS 17, *)
public struct FNWCallbackIntent: AppIntent {
  public static var title: LocalizedStringResource = "Widget action"
  public static var isDiscoverable: Bool = false

  @Parameter(title: "URL")
  public var url: URL?

  @Parameter(title: "App Group")
  public var appGroup: String?

  public init() {}

  public init(url: URL?, appGroup: String?) {
    self.url = url
    self.appGroup = appGroup
  }

  public func perform() async throws -> some IntentResult {
    // Returns once the Dart callback has finished.
    await HomeWidgetBackgroundWorker.run(url: url, appGroup: appGroup ?? "")
    // Redraw with what the callback saved, even if its own update request
    // raced the intent (seen on the first tap after a cold start).
    WidgetCenter.shared.reloadAllTimelines()
    return .result()
  }
}

// Run the intent in the app process, where the Flutter engine lives.
@available(iOS 17, *)
extension FNWCallbackIntent: ForegroundContinuableIntent {}
''';

const _callbackIntentStub = '''
/// Stand-in for the app's FNWCallbackIntent (ios/Runner/FNWCallbackIntent.swift).
/// Same name and parameters; the system performs the app's version.
@available(iOS 17, *)
struct FNWCallbackIntent: AppIntent {
  static var title: LocalizedStringResource = "Widget action"
  static var isDiscoverable: Bool = false

  @Parameter(title: "URL")
  var url: URL?

  @Parameter(title: "App Group")
  var appGroup: String?

  init() {}

  init(url: URL?, appGroup: String?) {
    self.url = url
    self.appGroup = appGroup
  }

  func perform() async throws -> some IntentResult { .result() }
}
''';

class _IosEmitter {
  final List<WidgetIR> widgets;
  final ProjectConfig config;

  _IosEmitter(this.widgets, this.config);

  String emit() {
    final out = StringBuffer(_swiftHeader)
      ..writeln()
      ..writeln('import AppIntents')
      ..writeln('import CoreText')
      ..writeln('import SwiftUI')
      ..writeln('import WidgetKit')
      ..writeln()
      ..writeln(_runtime())
      ..writeln(_callbackIntentStub);
    for (final w in widgets) {
      out.writeln(_widget(w));
    }
    final configurable = widgets.any((w) => w.options.isNotEmpty);
    void bundle(String name, {required bool ios17}) {
      if (ios17) out.writeln('@available(iOS 17, *)');
      out.writeln('struct $name: WidgetBundle {');
      out.writeln('  var body: some Widget {');
      if (widgets.isEmpty) out.writeln('    FNWPlaceholderWidget()');
      for (final w in widgets) {
        final configurableWidget = ios17 && w.options.isNotEmpty;
        out.writeln(
          '    FNW${w.name}${configurableWidget ? 'Configurable' : ''}Widget()',
        );
      }
      out.writeln('  }');
      out.writeln('}\n');
    }

    if (!configurable) {
      out.writeln('@main');
      bundle('FNWWidgetBundle', ios17: false);
    } else {
      // A bundle cannot branch on the OS version; pick one at launch.
      // Choices per widget copy need iOS 17; older versions get the
      // initial choices.
      bundle('FNWWidgetBundle', ios17: false);
      bundle('FNWWidgetBundle17', ios17: true);
      out.writeln('@main');
      out.writeln('enum FNWWidgetsMain {');
      out.writeln('  static func main() {');
      out.writeln('    if #available(iOS 17, *) {');
      out.writeln('      FNWWidgetBundle17.main()');
      out.writeln('    } else {');
      out.writeln('      FNWWidgetBundle.main()');
      out.writeln('    }');
      out.writeln('  }');
      out.writeln('}');
    }
    if (widgets.isEmpty) out.writeln(_placeholderWidget);
    return out.toString();
  }

  String _runtime() {
    final initial = StringBuffer();
    for (final w in widgets) {
      initial.writeln('    ${swiftString(w.name)}: ${_dict(w.initialValues)},');
    }
    final appGroup = config.iosAppGroup ?? '';
    return '''
struct FNWRefresh {
  let url: String
  let every: TimeInterval
  let values: [String: String]
  let headers: [String: String]
  let option: String?
}

struct FNWEntry: TimelineEntry {
  let date: Date
  let v: [String: String]
}

enum FNW {
  static let appGroup = ${swiftString(appGroup)}
  static var store: UserDefaults? { UserDefaults(suiteName: appGroup) }

  static let initialValues: [String: [String: String]] = [
${initial.isEmpty ? '    :\n' : initial}  ]

  static func timeline(_ widget: String) -> [(Date, [String: String])] {
    guard let json = store?.string(forKey: "fnw.\\(widget).__timeline"),
      let data = json.data(using: .utf8),
      let array = (try? JSONSerialization.jsonObject(with: data)) as? [[String: Any]]
    else { return [] }
    return array.compactMap { entry -> (Date, [String: String])? in
      guard let millis = (entry["t"] as? NSNumber)?.doubleValue else { return nil }
      let values = (entry["v"] as? [String: Any] ?? [:]).mapValues { "\\(\$0)" }
      return (Date(timeIntervalSince1970: millis / 1000), values)
    }.sorted { \$0.0 < \$1.0 }
  }

  /// Values at [date]: stored, then the active timeline entry, then the
  /// NWOption choices of this widget copy and values saved for them.
  static func values(
    _ widget: String, at date: Date, timeline: [(Date, [String: String])],
    options: [(String, String)] = []
  ) -> [String: String] {
    var result = initialValues[widget] ?? [:]
    let active = timeline.last(where: { \$0.0 <= date })?.1 ?? [:]
    if let store = store {
      for key in Array(result.keys) {
        if let value = store.object(forKey: "fnw.\\(widget).\\(key)") {
          result[key] = "\\(value)"
        }
      }
    }
    result.merge(active) { _, new in new }
    for (option, choice) in options { result[option] = choice }
    if !options.isEmpty {
      for key in Array(result.keys) where !options.contains(where: { \$0.0 == key }) {
        for (_, choice) in options {
          let saved = store?.object(forKey: "fnw.\\(widget).\\(key)@\\(choice)").map { "\\(\$0)" }
          if let value = active["\\(key)@\\(choice)"] ?? saved {
            result[key] = value
            break
          }
        }
      }
    }
    return result
  }

  static func entries(
    _ widget: String, clock: Bool, liveDate: Bool, timers: [String],
    options: [(String, String)] = [], refreshEvery: TimeInterval? = nil
  ) -> Timeline<FNWEntry> {
    let now = Date()
    let timeline = timeline(widget)
    var dates: Set<Date> = [now]
    for (date, _) in timeline where date > now { dates.insert(date) }
    let current = values(widget, at: now, timeline: timeline, options: options)
    for key in timers {
      if let target = date(current[key]), target > now { dates.insert(target) }
    }
    let calendar = Calendar.current
    if clock, let minute = calendar.dateInterval(of: .minute, for: now)?.start {
      for i in 1...60 { dates.insert(minute.addingTimeInterval(Double(i) * 60)) }
    }
    if liveDate, let midnight = calendar.date(byAdding: .day, value: 1, to: calendar.startOfDay(for: now)) {
      dates.insert(midnight)
    }
    let entries = dates.sorted().map {
      FNWEntry(date: \$0, v: values(widget, at: \$0, timeline: timeline, options: options))
    }
    var policy: TimelineReloadPolicy = entries.count > 1 ? .atEnd : .never
    if let every = refreshEvery {
      // Reload for the next download, or earlier when the entries run out.
      var next = now.addingTimeInterval(every)
      if entries.count > 1, let last = entries.last?.date, last < next { next = last }
      policy = .after(next)
    }
    return Timeline(entries: entries, policy: policy)
  }

  /// Downloads NWRefresh data when it is due and saves it like the app
  /// would (for one NWOption choice when the URL uses it).
  static func refresh(_ widget: String, _ spec: FNWRefresh, options: [(String, String)] = []) async {
    let current = values(widget, at: Date(), timeline: timeline(widget), options: options)
    let suffix = spec.option.flatMap { current[\$0] }.map { "@\\(\$0)" } ?? ""
    let stamp = "fnw.\\(widget).__fetched\\(suffix)"
    let last = store?.double(forKey: stamp) ?? 0
    guard Date().timeIntervalSince1970 - last >= spec.every - 60,
      let url = URL(string: resolve(spec.url, current))
    else { return }
    var request = URLRequest(url: url, timeoutInterval: 15)
    for (name, value) in spec.headers { request.setValue(value, forHTTPHeaderField: name) }
    guard let (data, response) = try? await URLSession.shared.data(for: request),
      ((response as? HTTPURLResponse)?.statusCode ?? 0) < 300,
      let json = try? JSONSerialization.jsonObject(with: data, options: [.fragmentsAllowed])
    else { return }
    for (key, path) in spec.values {
      if let value = lookup(json, path) { store?.set(value, forKey: "fnw.\\(widget).\\(key)\\(suffix)") }
    }
    store?.set(Date().timeIntervalSince1970, forKey: stamp)
  }

  /// `items.0.title` in decoded JSON, as text.
  static func lookup(_ json: Any, _ path: String) -> String? {
    var current: Any? = json
    for part in path.split(separator: ".") {
      if let array = current as? [Any], let index = Int(part) {
        current = index < array.count ? array[index] : nil
      } else if let object = current as? [String: Any] {
        current = object[String(part)]
      } else {
        return nil
      }
    }
    switch current {
    case let text as String: return text
    case let number as NSNumber:
      if CFGetTypeID(number) == CFBooleanGetTypeID() { return number.boolValue ? "true" : "false" }
      return number.stringValue
    case .some(let value) where !(value is NSNull):
      guard let data = try? JSONSerialization.data(withJSONObject: value) else { return nil }
      return String(data: data, encoding: .utf8)
    default: return nil
    }
  }

  static func resolve(_ template: String, _ v: [String: String]) -> String {
    guard let regex = try? NSRegularExpression(pattern: "\\\\{([A-Za-z_][A-Za-z0-9_]*)\\\\}") else {
      return template
    }
    let text = template as NSString
    var out = ""
    var last = 0
    for match in regex.matches(in: template, range: NSRange(location: 0, length: text.length)) {
      out += text.substring(with: NSRange(location: last, length: match.range.location - last))
      out += v[text.substring(with: match.range(at: 1))] ?? ""
      last = match.range.location + match.range.length
    }
    return out + text.substring(from: last)
  }

  static func date(_ value: String?) -> Date? {
    guard let value = value, let millis = Double(value) else { return nil }
    return Date(timeIntervalSince1970: millis / 1000)
  }

  static func number(_ value: String?) -> Double { Double(value ?? "") ?? 0 }

  /// A font file from the extension's Fonts folder, registered on first use.
  static func font(_ file: String, size: CGFloat) -> Font {
    let name = (file as NSString).deletingPathExtension
    let ext = (file as NSString).pathExtension
    guard let url = Bundle.main.url(forResource: name, withExtension: ext, subdirectory: "Fonts"),
      let provider = CGDataProvider(url: url as CFURL),
      let font = CGFont(provider),
      let postScriptName = font.postScriptName as String?
    else { return .system(size: size) }
    CTFontManagerRegisterFontsForURL(url as CFURL, .process, nil)
    return .custom(postScriptName, fixedSize: size)
  }

  static func fraction(_ value: String?, max: Double) -> Double {
    max <= 0 ? 0 : Swift.min(Swift.max(number(value) / max, 0), 1)
  }

  static func format(_ date: Date?, _ pattern: String) -> String {
    guard let date = date else { return "" }
    let formatter = DateFormatter()
    formatter.locale = Locale.current
    formatter.dateFormat = pattern
    return formatter.string(from: date)
  }

  static func clock(_ date: Date, use24Hour: Bool?) -> String {
    let formatter = DateFormatter()
    formatter.locale = Locale.current
    switch use24Hour {
    case .some(true): formatter.dateFormat = "HH:mm"
    case .some(false): formatter.dateFormat = "h:mm"
    case .none:
      let system = DateFormatter.dateFormat(fromTemplate: "jmm", options: 0, locale: Locale.current) ?? "HH:mm"
      formatter.dateFormat = system.replacingOccurrences(of: "a", with: "")
        .trimmingCharacters(in: .whitespaces)
    }
    return formatter.string(from: date)
  }

  static func check(_ kind: String, _ value: String?, _ arg: String?) -> Bool {
    let value = value ?? ""
    switch kind {
    case "isTrue": return value == "true"
    case "isFalse": return value != "true"
    case "isEmpty": return value.isEmpty
    case "notEmpty": return !value.isEmpty
    case "equals": return value == arg
    case "greaterThan": return number(value) > number(arg)
    default: return false
    }
  }

  static func color(_ light: UInt32, _ dark: UInt32) -> Color {
    func make(_ argb: UInt32) -> UIColor {
      UIColor(
        red: CGFloat((argb >> 16) & 0xFF) / 255,
        green: CGFloat((argb >> 8) & 0xFF) / 255,
        blue: CGFloat(argb & 0xFF) / 255,
        alpha: CGFloat((argb >> 24) & 0xFF) / 255)
    }
    return Color(UIColor { \$0.userInterfaceStyle == .dark ? make(dark) : make(light) })
  }

  static func image(_ path: String?) -> UIImage? {
    guard let path = path, !path.isEmpty, let image = UIImage(contentsOfFile: path) else {
      return nil
    }
    let longest = Swift.max(image.size.width, image.size.height)
    guard longest > 800 else { return image }
    let scale = 800 / longest
    return image.preparingThumbnail(
      of: CGSize(width: image.size.width * scale, height: image.size.height * scale)) ?? image
  }

  /// Applies a native action URL (increment, toggle, ...). Mirrors the
  /// Kotlin and Dart implementations.
  static func apply(_ url: URL) {
    guard let components = URLComponents(url: url, resolvingAgainstBaseURL: false) else { return }
    var q: [String: String] = [:]
    for item in components.queryItems ?? [] { q[item.name] = item.value ?? "" }
    guard let widget = q["w"], let key = q["k"] else { return }
    let storageKey = "fnw.\\(widget).\\(key)"
    let current = store?.object(forKey: storageKey).map { "\\(\$0)" }
      ?? initialValues[widget]?[key] ?? ""
    var next = current
    switch q["op"] {
    case "inc", "dec":
      let by = Int(q["by"] ?? "1") ?? 1
      var n = (Int(current) ?? Int(Double(current) ?? 0)) + (q["op"] == "inc" ? by : -by)
      if let min = Int(q["min"] ?? "") { n = Swift.max(n, min) }
      if let max = Int(q["max"] ?? "") { n = Swift.min(n, max) }
      next = String(n)
    case "toggle": next = current == "true" ? "false" : "true"
    case "set": next = q["v"] ?? ""
    case "cycle":
      let data = (q["vs"] ?? "[]").data(using: .utf8) ?? Data()
      let values = ((try? JSONSerialization.jsonObject(with: data)) as? [String]) ?? []
      if !values.isEmpty {
        let index = values.firstIndex(of: current).map { \$0 + 1 } ?? 0
        next = values[index % values.count]
      }
    default: break
    }
    store?.set(next, forKey: storageKey)
  }
}

/// Runs a native action inside the widget extension (iOS 17+).
@available(iOS 17, *)
struct FNWActionIntent: AppIntent {
  static var title: LocalizedStringResource = "Update widget"
  static var isDiscoverable: Bool = false

  @Parameter(title: "URL")
  var url: URL?

  init() {}

  init(url: URL) {
    self.url = url
  }

  func perform() async throws -> some IntentResult {
    if let url = url { FNW.apply(url) }
    return .result()
  }
}

enum FNWActionKind { case native, callback, open }

/// A tappable area. iOS 17+ runs native actions and callbacks without
/// opening the app; older versions open the app, which handles the URL.
struct FNWButton<Label: View>: View {
  let url: URL
  let kind: FNWActionKind
  @ViewBuilder let label: () -> Label

  var body: some View {
    if #available(iOS 17, *) {
      interactive
    } else {
      Link(destination: url) { label() }
    }
  }

  @available(iOS 17, *)
  @ViewBuilder var interactive: some View {
    switch kind {
    case .native:
      Button(intent: FNWActionIntent(url: url)) { label() }.buttonStyle(.plain)
    case .callback:
      Button(intent: FNWCallbackIntent(url: url, appGroup: FNW.appGroup)) { label() }
        .buttonStyle(.plain)
    case .open:
      Link(destination: url) { label() }
    }
  }
}

/// Clock face with hour and minute hands, redrawn every minute by the
/// timeline. iOS widgets cannot animate, so there is no second hand.
struct FNWAnalogClock: View {
  let date: Date
  let size: CGFloat
  let face: Color
  let border: Color?
  let ticks: Color
  let hands: Color
  let allTicks: Bool

  var body: some View {
    let calendar = Calendar.current
    let hour = Double(calendar.component(.hour, from: date) % 12)
    let minute = Double(calendar.component(.minute, from: date))
    ZStack {
      Circle().fill(face)
      if let border = border {
        Circle().strokeBorder(border, lineWidth: size * 0.02)
      }
      ForEach(0..<12, id: \\.self) { i in
        if allTicks || i % 3 == 0 {
          Capsule()
            .fill(ticks)
            .frame(width: size * (i % 3 == 0 ? 0.035 : 0.022), height: size * (i % 3 == 0 ? 0.07 : 0.04))
            .offset(y: -size * 0.395)
            .rotationEffect(.degrees(Double(i) * 30))
        }
      }
      hand(length: 0.23, width: 0.055, degrees: (hour + minute / 60) * 30)
      hand(length: 0.38, width: 0.035, degrees: minute * 6)
      Circle().fill(hands).frame(width: size * 0.07, height: size * 0.07)
    }
    .frame(width: size, height: size)
  }

  private func hand(length: CGFloat, width: CGFloat, degrees: Double) -> some View {
    Capsule()
      .fill(hands)
      .frame(width: size * width, height: size * length)
      .offset(y: -size * length / 2)
      .rotationEffect(.degrees(degrees))
  }
}

extension View {
  @ViewBuilder func fnwBackground(_ color: Color) -> some View {
    if #available(iOS 17, *) {
      self.containerBackground(for: .widget) { color }
    } else {
      self.background(color)
    }
  }
}

extension WidgetFamily {
  var fnwIsAccessory: Bool {
    switch self {
    case .accessoryCircular, .accessoryRectangular, .accessoryInline: return true
    default: return false
    }
  }
}

extension WidgetConfiguration {
  func fnwContentMarginsDisabled() -> some WidgetConfiguration {
    if #available(iOSApplicationExtension 17.0, *) {
      return self.contentMarginsDisabled()
    } else {
      return self
    }
  }
}
''';
  }

  String _dict(Map<String, String> values) {
    if (values.isEmpty) return '[:]';
    return '[${[for (final MapEntry(:key, :value) in values.entries) '${swiftString(key)}: ${swiftString(value)}'].join(', ')}]';
  }

  String _widget(WidgetIR w) {
    final name = 'FNW${w.name}';
    final families = [for (final s in w.sizes) _family(s)].join(', ');
    final timers = [for (final t in w.timerFields) swiftString(t)].join(', ');
    final p = w.padding;
    final b = StringBuffer();

    final kind = swiftString(w.name);
    final refresh = w.refresh;
    String entries(String options) =>
        'FNW.entries($kind, clock: ${w.hasClock}, liveDate: ${w.hasLiveDate}, '
        'timers: [$timers], options: $options'
        '${refresh == null ? '' : ', refreshEvery: ${refresh.every}'})';
    String values(String options) =>
        'FNW.values($kind, at: Date(), timeline: FNW.timeline($kind), options: $options)';
    final download = refresh == null
        ? null
        : (String options) =>
              'await FNW.refresh($kind, ${name}Refresh, options: $options)';

    if (refresh != null) {
      b.writeln(
        'let ${name}Refresh = FNWRefresh(url: ${swiftString(refresh.url)}, '
        'every: ${refresh.every}, values: ${_dict(refresh.values)}, '
        'headers: ${_dict(refresh.headers)}, '
        'option: ${refresh.option == null ? 'nil' : swiftString(refresh.option!)})\n',
      );
    }

    // Without per-copy choices (and before iOS 17) options keep their initial value.
    final initialOptions =
        '[${w.options.map((o) => '(${swiftString(o.key)}, ${swiftString(o.initial)})').join(', ')}]';
    b.writeln('struct ${name}Provider: TimelineProvider {');
    b.writeln('  func placeholder(in context: Context) -> FNWEntry {');
    b.writeln('    FNWEntry(date: Date(), v: FNW.initialValues[$kind] ?? [:])');
    b.writeln('  }\n');
    b.writeln(
      '  func getSnapshot(in context: Context, completion: @escaping (FNWEntry) -> Void) {',
    );
    b.writeln(
      '    completion(FNWEntry(date: Date(), v: ${values(initialOptions)}))',
    );
    b.writeln('  }\n');
    b.writeln(
      '  func getTimeline(in context: Context, completion: @escaping (Timeline<FNWEntry>) -> Void) {',
    );
    if (download == null) {
      b.writeln('    completion(${entries(initialOptions)})');
    } else {
      b.writeln('    Task {');
      b.writeln('      ${download(initialOptions)}');
      b.writeln('      completion(${entries(initialOptions)})');
      b.writeln('    }');
    }
    b.writeln('  }');
    b.writeln('}\n');

    if (w.options.isNotEmpty) {
      for (final o in w.options) {
        final type = '$name${upperFirst(o.key)}Option';
        b.writeln('@available(iOS 17, *)');
        b.writeln('enum $type: String, AppEnum {');
        for (final (i, c) in o.choices.indexed) {
          b.writeln('  case c$i = ${swiftString(c)}');
        }
        b.writeln(
          '  static var typeDisplayRepresentation: TypeDisplayRepresentation = ${swiftString(o.label)}',
        );
        b.writeln(
          '  static var caseDisplayRepresentations: [$type: DisplayRepresentation] = [',
        );
        for (final (i, c) in o.choices.indexed) {
          b.writeln('    .c$i: ${swiftString(c)},');
        }
        b.writeln('  ]');
        b.writeln('}\n');
      }
      b.writeln('@available(iOS 17, *)');
      b.writeln('struct ${name}Configuration: WidgetConfigurationIntent {');
      b.writeln(
        '  static var title: LocalizedStringResource = ${swiftString(w.displayName)}\n',
      );
      for (final o in w.options) {
        b.writeln(
          '  @Parameter(title: ${swiftString(o.label)}, '
          'default: .c${o.choices.indexOf(o.initial)})',
        );
        b.writeln('  var fnw_${o.key}: $name${upperFirst(o.key)}Option');
      }
      b.writeln();
      b.writeln('  var fnwOptions: [(String, String)] {');
      b.writeln(
        '    [${w.options.map((o) => '(${swiftString(o.key)}, fnw_${o.key}.rawValue)').join(', ')}]',
      );
      b.writeln('  }');
      b.writeln('}\n');

      b.writeln('@available(iOS 17, *)');
      b.writeln(
        'struct ${name}ConfigurableProvider: AppIntentTimelineProvider {',
      );
      b.writeln('  func placeholder(in context: Context) -> FNWEntry {');
      b.writeln(
        '    FNWEntry(date: Date(), v: FNW.initialValues[$kind] ?? [:])',
      );
      b.writeln('  }\n');
      b.writeln(
        '  func snapshot(for configuration: ${name}Configuration, in context: Context) async -> FNWEntry {',
      );
      b.writeln(
        '    FNWEntry(date: Date(), v: ${values('configuration.fnwOptions')})',
      );
      b.writeln('  }\n');
      b.writeln(
        '  func timeline(for configuration: ${name}Configuration, in context: Context) async -> Timeline<FNWEntry> {',
      );
      if (download != null) {
        b.writeln('    ${download('configuration.fnwOptions')}');
      }
      b.writeln('    return ${entries('configuration.fnwOptions')}');
      b.writeln('  }');
      b.writeln('}\n');
    }

    b.writeln('struct ${name}View: View {');
    b.writeln('  let entry: FNWEntry');
    if (w.sizeLayouts.isNotEmpty || w.hasLockScreen) {
      b.writeln('  @Environment(\\.widgetFamily) var family');
    }
    final padding =
        'EdgeInsets(top: ${num2(p.top)}, leading: ${num2(p.start)}, '
        'bottom: ${num2(p.bottom)}, trailing: ${num2(p.end)})';
    final background = _color(w.background);
    b.writeln();
    b.writeln('  var body: some View {');
    b.writeln('    content');
    if (w.hasLockScreen) {
      // The Lock Screen tints widgets and draws no background.
      b.writeln(
        '      .padding(family.fnwIsAccessory ? EdgeInsets() : $padding)',
      );
      b.writeln(
        '      .fnwBackground(family.fnwIsAccessory ? Color.clear : $background)',
      );
    } else {
      b.writeln('      .padding($padding)');
      b.writeln('      .fnwBackground($background)');
    }
    b.writeln(
      '      .widgetURL(URL(string: ${swiftString(actionUri(w.name, w.onTap))}))',
    );
    b.writeln('  }\n');
    b.writeln('  @ViewBuilder var content: some View {');
    if (w.sizeLayouts.isEmpty) {
      b.writeln('    main');
    } else {
      b.writeln('    switch family {');
      for (final size in w.sizeLayouts.keys) {
        b.writeln('    case ${_family(size)}: $size');
      }
      b.writeln('    default: main');
      b.writeln('    }');
    }
    b.writeln('  }\n');
    for (final MapEntry(key: variant, value: layout) in w.layouts.entries) {
      b.writeln('  @ViewBuilder var $variant: some View {');
      b.write(_root(w, layout, '    '));
      b.writeln('  }\n');
    }
    b.writeln('}\n');

    void widget(String type, String configuration, {bool ios17 = false}) {
      if (ios17) b.writeln('@available(iOS 17, *)');
      b.writeln('struct $type: Widget {');
      b.writeln('  let kind: String = $kind\n');
      b.writeln('  var body: some WidgetConfiguration {');
      b.writeln('    $configuration { entry in');
      b.writeln('      ${name}View(entry: entry)');
      b.writeln('    }');
      b.writeln('    .configurationDisplayName(${swiftString(w.displayName)})');
      b.writeln('    .description(${swiftString(w.description)})');
      b.writeln('    .supportedFamilies([$families])');
      b.writeln('    .fnwContentMarginsDisabled()');
      b.writeln('  }');
      b.writeln('}');
    }

    widget(
      '${name}Widget',
      'StaticConfiguration(kind: kind, provider: ${name}Provider())',
    );
    if (w.options.isNotEmpty) {
      b.writeln();
      widget(
        '${name}ConfigurableWidget',
        'AppIntentConfiguration(kind: kind, intent: ${name}Configuration.self, '
            'provider: ${name}ConfigurableProvider())',
        ios17: true,
      );
    }
    return b.toString();
  }

  String _family(String size) => lockScreenSizes.contains(size)
      ? '.accessory${upperFirst(size)}'
      : '.system${upperFirst(size)}';

  /// The layout root fills the widget, aligned like its Android counterpart.
  String _root(WidgetIR w, NodeIR n, String indent) {
    final alignment = switch (n.type) {
      'column' => _frameAlignment(
        vertical: _mainToVertical(n.prop<String>('main')),
        horizontal: _crossToHorizontal(n.prop<String>('cross')),
      ),
      'row' => _frameAlignment(
        vertical: _crossToVertical(n.prop<String>('cross')),
        horizontal: _mainToHorizontal(n.prop<String>('main')),
      ),
      'stack' || 'box' => _alignment(n.prop<String>('alignment')),
      _ => '.center',
    };
    final b = StringBuffer();
    b.write(_node(w, n, indent));
    b.writeln(
      '$indent  .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: $alignment)',
    );
    return b.toString();
  }

  String _node(
    WidgetIR w,
    NodeIR n,
    String i, {
    bool stretchHorizontal = false,
    bool stretchVertical = false,
  }) {
    final b = StringBuffer();
    void line(String s) => b.writeln('$i$s');

    switch (n.type) {
      case 'column':
      case 'row':
        final vertical = n.type == 'column';
        final cross = n.prop<String>('cross');
        final main = n.prop<String>('main');
        final stackAlignment = vertical
            ? switch (cross) {
                'center' => '.center',
                'end' => '.trailing',
                _ => '.leading',
              }
            : switch (cross) {
                'center' => '.center',
                'end' => '.bottom',
                _ => '.top',
              };
        // Main-axis start/center/end come from the frame the parent (or the
        // root) puts around the stack; only spaceBetween needs spacers.
        line(
          '${vertical ? 'VStack' : 'HStack'}(alignment: $stackAlignment, '
          'spacing: ${num2(n.number('spacing') ?? 0)}) {',
        );
        for (final (index, child) in n.children.indexed) {
          if (index > 0 && main == 'spaceBetween') {
            line('  Spacer(minLength: 0)');
          }
          b.write(
            _node(
              w,
              child,
              '$i  ',
              stretchHorizontal: vertical && cross == 'stretch',
              stretchVertical: !vertical && cross == 'stretch',
            ),
          );
        }
        line('}');
      case 'list':
        // No scrolling on iOS: the items that fit, from the top. As an
        // overlay the full column does not make the widget taller.
        line('Color.clear');
        line('  .overlay(alignment: .top) {');
        b.write(
          _node(
            w,
            NodeIR('column', {
              'main': 'start',
              'cross': 'stretch',
              'spacing': n.number('spacing') ?? 0,
            }, n.children),
            '$i    ',
          ),
        );
        line('  }');
        line('  .clipped()');
      case 'stack':
        line('ZStack(alignment: ${_alignment(n.prop<String>('alignment'))}) {');
        for (final child in n.children) {
          b.write(_node(w, child, '$i  '));
        }
        line('}');
      case 'box':
        final alignment = _alignment(n.prop<String>('alignment'));
        if (n.children.isEmpty) {
          line('Color.clear');
        } else {
          line('ZStack(alignment: $alignment) {');
          b.write(_node(w, n.children.first, '$i  '));
          line('}');
        }
        final padding = n.insets('padding');
        if (!padding.isZero) {
          line(
            '  .padding(EdgeInsets(top: ${num2(padding.top)}, leading: ${num2(padding.start)}, '
            'bottom: ${num2(padding.bottom)}, trailing: ${num2(padding.end)}))',
          );
        }
        final width = n.number('width');
        final height = n.number('height');
        if (width != null || height != null) {
          line(
            '  .frame(${[if (width != null) 'width: ${num2(width)}', if (height != null) 'height: ${num2(height)}'].join(', ')}, alignment: $alignment)',
          );
        }
        if (n.prop<bool>('expand')) {
          line(
            '  .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: $alignment)',
          );
        }
        final color = n.color('color');
        final gradient = n.props['gradient'] as Map?;
        final radius = num2(n.number('radius') ?? 0);
        final shape =
            'RoundedRectangle(cornerRadius: $radius, style: .continuous)';
        if (gradient != null) {
          final colors = [
            for (final c in gradient['colors'] as List)
              _color(ColorIR.fromJson((c as Map).cast())),
          ].join(', ');
          line(
            '  .background($shape.fill(LinearGradient(colors: [$colors], '
            'startPoint: ${_alignment(gradient['begin'] as String)}, '
            'endPoint: ${_alignment(gradient['end'] as String)})))',
          );
        } else if (color != null) {
          line('  .background($shape.fill(${_color(color)}))');
        }
        final border = n.color('borderColor');
        if (border != null) {
          line(
            '  .overlay($shape.strokeBorder(${_color(border)}, '
            'lineWidth: ${num2(n.number('borderWidth') ?? 1)}))',
          );
        }
      case 'analog':
        // `secondHand` is Android-only: iOS widgets cannot animate one.
        final borderColor = n.color('border');
        line(
          'FNWAnalogClock(date: entry.date, size: ${num2(n.number('size') ?? 120)}, '
          'face: ${_color(n.color('face')!)}, '
          'border: ${borderColor == null ? 'nil' : _color(borderColor)}, '
          'ticks: ${_color(n.color('ticks')!)}, '
          'hands: ${_color(n.color('hands')!)}, '
          'allTicks: ${n.prop<bool>('allTicks')})',
        );
      case 'spacer':
        line('Spacer(minLength: 0)');
      case 'text':
        final text = n.prop<String>('text');
        if (templateKeys(text).isEmpty) {
          line('Text(verbatim: ${swiftString(text)})');
        } else {
          line('Text(verbatim: FNW.resolve(${swiftString(text)}, entry.v))');
        }
        b.write(_textModifiers(n, i));
      case 'rich':
        final parts = [
          for (final (text, style) in n.spans)
            '${templateKeys(text).isEmpty ? 'Text(verbatim: ${swiftString(text)})' : 'Text(verbatim: FNW.resolve(${swiftString(text)}, entry.v))'}'
                '.font(${_font(style)})'
                '${style.italic ? '.italic()' : ''}'
                '.foregroundColor(${_color(style.color ?? labelColor)})',
        ];
        line('(${parts.join('\n$i  + ')})');
        if (n.style.monospacedDigits) line('  .monospacedDigit()');
        b.write(_lineModifiers(n, i));
      case 'clock':
        if (n.prop<bool>('seconds')) {
          line(
            'Text(Calendar.current.startOfDay(for: entry.date), style: .timer)',
          );
        } else {
          final use24 = n.props['use24Hour'] as bool?;
          line(
            'Text(verbatim: FNW.clock(entry.date, use24Hour: ${use24 == null ? 'nil' : '$use24'}))',
          );
        }
        b.write(_textModifiers(n, i));
      case 'date':
        final field = n.props['field'] as String?;
        final pattern = swiftString(n.prop<String>('pattern'));
        line(
          field == null
              ? 'Text(verbatim: FNW.format(entry.date, $pattern))'
              : 'Text(verbatim: FNW.format(FNW.date(entry.v[${swiftString(field)}]), $pattern))',
        );
        b.write(_textModifiers(n, i));
      case 'timer':
        final field = swiftString(n.prop<String>('field'));
        line('Group {');
        line('  if let target = FNW.date(entry.v[$field]) {');
        line('    Text(target, style: .timer)');
        line('  } else {');
        line('    Text(verbatim: "0:00")');
        line('  }');
        line('}');
        b.write(_textModifiers(n, i));
      case 'image':
        final field = swiftString(n.prop<String>('field'));
        final width = n.number('width');
        final height = n.number('height');
        final frame = width != null || height != null
            ? '.frame(${[if (width != null) 'width: ${num2(width)}', if (height != null) 'height: ${num2(height)}'].join(', ')})'
            : null;
        line('Group {');
        line('  if let image = FNW.image(entry.v[$field]) {');
        final fit = n.prop<String>('fit');
        if (fit == 'cover') {
          // A filled image is larger than its frame; as an overlay it does
          // not push its siblings around.
          line('    Color.clear');
          if (frame != null) line('      $frame');
          line(
            '      .overlay(Image(uiImage: image).resizable()'
            '.aspectRatio(contentMode: .fill))',
          );
        } else {
          line(
            '    Image(uiImage: image).resizable()'
            '${fit == 'fill' ? '' : '.aspectRatio(contentMode: .fit)'}',
          );
          if (frame != null) line('      $frame');
        }
        line('      .clipped()');
        line('  }');
        line('}');
      case 'icon':
        final size = num2(n.number('width')!);
        line('Image(systemName: ${swiftString(n.prop<String>('sf'))})');
        line('  .resizable()');
        line('  .scaledToFit()');
        line('  .frame(width: $size, height: $size)');
        line('  .foregroundColor(${_color(n.color('color') ?? labelColor)})');
      case 'progress':
        final color = n.color('color');
        final fraction =
            'FNW.fraction(entry.v[${swiftString(n.prop<String>('field'))}], '
            'max: ${n.number('max')})';
        final size = n.number('size');
        if (size != null) {
          final thickness = num2(n.number('thickness')!);
          line('ZStack {');
          line(
            '  Circle().stroke(${_color(n.color('track') ?? progressTrackColor)}, '
            'lineWidth: $thickness)',
          );
          line('  Circle()');
          line('    .trim(from: 0, to: $fraction)');
          line(
            '    .stroke(${_color(color ?? progressColor)}, '
            'style: StrokeStyle(lineWidth: $thickness, lineCap: .round))',
          );
          line('    .rotationEffect(.degrees(-90))');
          line('}');
          // The stroke is centered on the path; inset it to stay inside size.
          line('  .padding(${num2(n.number('thickness')! / 2)})');
          line('  .frame(width: ${num2(size)}, height: ${num2(size)})');
        } else if (n.color('track') case final track?) {
          // ProgressView cannot recolor its track; draw the bar instead.
          line('GeometryReader { g in');
          line('  ZStack(alignment: .leading) {');
          line('    Capsule().fill(${_color(track)})');
          line(
            '    Capsule().fill(${_color(color ?? progressColor)})'
            '.frame(width: g.size.width * $fraction)',
          );
          line('  }');
          line('}');
          line('  .frame(height: 4)');
        } else {
          line('ProgressView(value: $fraction)');
          if (color != null) line('  .tint(${_color(color)})');
        }
      case 'button':
        final action = n.action;
        final kind = switch (action.kind) {
          ActionKind.openApp => '.open',
          ActionKind.callback => '.callback',
          _ => '.native',
        };
        line(
          'FNWButton(url: URL(string: ${swiftString(actionUri(w.name, action))})!, kind: $kind) {',
        );
        b.write(
          _node(
            w,
            n.children.first,
            '$i  ',
            stretchHorizontal: stretchHorizontal,
            stretchVertical: stretchVertical,
          ),
        );
        line('}');
      case 'if':
        final c = n.condition;
        line('Group {');
        line(
          '  if FNW.check(${swiftString(c.kind.name)}, entry.v[${swiftString(c.key)}], '
          '${c.value == null ? 'nil' : swiftString(c.value!)}) {',
        );
        b.write(
          _node(
            w,
            n.thenNode,
            '$i    ',
            stretchHorizontal: stretchHorizontal,
            stretchVertical: stretchVertical,
          ),
        );
        final orElse = n.elseNode;
        if (orElse != null) {
          line('  } else {');
          b.write(
            _node(
              w,
              orElse,
              '$i    ',
              stretchHorizontal: stretchHorizontal,
              stretchVertical: stretchVertical,
            ),
          );
        }
        line('  }');
        line('}');
      default:
        throw StateError('Unknown node type ${n.type}');
    }

    // Spacers and expanding boxes already grow; everything else stretches
    // across a column/row with `crossAxisAlignment: stretch`.
    final grows =
        n.type == 'spacer' ||
        n.type == 'list' ||
        (n.type == 'box' && n.prop<bool>('expand'));
    if (!grows && n.type != 'if' && n.type != 'button') {
      if (stretchHorizontal) {
        final align = switch (n.props['align']) {
          'center' => '.center',
          'end' => '.trailing',
          _ => '.leading',
        };
        line('  .frame(maxWidth: .infinity, alignment: $align)');
      }
      if (stretchVertical) {
        line('  .frame(maxHeight: .infinity, alignment: .top)');
      }
    }
    return b.toString();
  }

  String _font(TextStyleIR style) => style.font == null
      ? '.system(size: ${num2(style.size)}, weight: ${_weight(style.weight)})'
      : 'FNW.font(${swiftString(iosFontFile(style.font!))}, size: ${num2(style.size)})';

  String _weight(String weight) => switch (weight) {
    'light' => '.light',
    'medium' => '.medium',
    'semibold' => '.semibold',
    'bold' => '.bold',
    _ => '.regular',
  };

  String _textModifiers(NodeIR n, String i) {
    final style = n.style;
    final b = StringBuffer();
    b.writeln('$i  .font(${_font(style)})');
    if (style.italic) b.writeln('$i  .italic()');
    if (style.monospacedDigits) b.writeln('$i  .monospacedDigit()');
    b.writeln('$i  .foregroundColor(${_color(style.color ?? labelColor)})');
    b.write(_lineModifiers(n, i));
    return b.toString();
  }

  /// Line limit and alignment, shared by plain and rich text.
  String _lineModifiers(NodeIR n, String i) {
    final b = StringBuffer();
    final maxLines = n.props['maxLines'] as int?;
    if (maxLines != null) b.writeln('$i  .lineLimit($maxLines)');
    final align = n.props['align'] as String? ?? 'start';
    b.writeln(
      '$i  .multilineTextAlignment(${switch (align) {
        'center' => '.center',
        'end' => '.trailing',
        _ => '.leading',
      }})',
    );
    return b.toString();
  }

  String _color(ColorIR c) =>
      'FNW.color(0x${c.light.substring(1)}, 0x${c.dark.substring(1)})';

  String _alignment(String a) => switch (a) {
    'topStart' => '.topLeading',
    'topCenter' => '.top',
    'topEnd' => '.topTrailing',
    'centerStart' => '.leading',
    'centerEnd' => '.trailing',
    'bottomStart' => '.bottomLeading',
    'bottomCenter' => '.bottom',
    'bottomEnd' => '.bottomTrailing',
    _ => '.center',
  };

  String _mainToVertical(String main) => switch (main) {
    'center' => 'center',
    'end' => 'bottom',
    _ => 'top',
  };

  String _mainToHorizontal(String main) => switch (main) {
    'center' => 'center',
    'end' => 'trailing',
    _ => 'leading',
  };

  String _crossToVertical(String cross) => switch (cross) {
    'center' => 'center',
    'end' => 'bottom',
    _ => 'top',
  };

  String _crossToHorizontal(String cross) => switch (cross) {
    'center' => 'center',
    'end' => 'trailing',
    _ => 'leading',
  };

  String _frameAlignment({
    required String vertical,
    required String horizontal,
  }) {
    if (vertical == 'center' && horizontal == 'center') return '.center';
    if (vertical == 'center') return '.$horizontal';
    if (horizontal == 'center') return '.$vertical';
    return '.$vertical${upperFirst(horizontal)}';
  }
}

const _placeholderWidget = '''

/// Shown until you declare a widget with @HomeScreenWidget and run build_runner.
struct FNWPlaceholderWidget: Widget {
  var body: some WidgetConfiguration {
    StaticConfiguration(kind: "FNWPlaceholder", provider: FNWPlaceholderProvider()) { _ in
      Text(verbatim: "Run build_runner").fnwBackground(Color.clear)
    }
    .configurationDisplayName("flutter_native_widget")
  }
}

struct FNWPlaceholderProvider: TimelineProvider {
  func placeholder(in context: Context) -> FNWEntry { FNWEntry(date: Date(), v: [:]) }
  func getSnapshot(in context: Context, completion: @escaping (FNWEntry) -> Void) {
    completion(FNWEntry(date: Date(), v: [:]))
  }
  func getTimeline(in context: Context, completion: @escaping (Timeline<FNWEntry>) -> Void) {
    completion(Timeline(entries: [FNWEntry(date: Date(), v: [:])], policy: .never))
  }
}
''';
